// Auto-generated coach images - embedded as rock-solid high-resolution data URLs
// to guarantee 100% offline & production reliability without network 404s.

export const COACH_IMAGES = {
  adewale: 'data:image/jpeg;base64,',
  soji: 'data:image/jpeg;base64,',
  esther: 'data:image/jpeg;base64,',
  kehinde: 'data:image/png;base64,',
  defaultLogo: '/images/cih-logo.png'
} as const;

export const getCoachImage = (coachIdOrName: string): string => {
  const query = (coachIdOrName || '').toLowerCase().trim();
  if (query.includes('adewale') || query.includes('oseni')) {
    return COACH_IMAGES.adewale;
  }
  if (query.includes('soji') || query.includes('megbowon')) {
    return COACH_IMAGES.soji;
  }
  if (query.includes('esther') || query.includes('ajayi')) {
    return COACH_IMAGES.esther;
  }
  if (query.includes('kehinde') || query.includes('ajasa')) {
    return COACH_IMAGES.kehinde;
  }
  return COACH_IMAGES.defaultLogo;
};
